 return {'id':id,'title':title,'year':year,'runtime':runtime,'rating':rating,'status':'unseen','tag':tag,'vibe':vibe,'dna':dna,'scores':dict(zip(['propulsion','belt','movement','emotion','comfort','maximalism','narrative','hooks','afterglow','replay'],s)),'why':why,'risk':risk,'songs':songs,'links':links,'enrichment':{'format':fmt,'musicalType':typ,'vocalStyle':vocal,'lyricalDensity':lyr,'musicDrivenPercent':music,'catharsis':cat,'rewatchability':re,'familiarityAdvantage':fam,'bestMood':moods,'friction':friction,'gatewaySongs':[{'song':a,'purpose':b} for a,b in gateway],'notes':notes,'provenance':[{'type':'editorial-analysis','source':'Musical Propulsion Engine expansion batch 2','scope':'interpretive scoring and fit analysis'}]}}
